function updateIncomeFields(){const form=document.querySelector('#income-form'),recurring=form.elements.income_kind.value==='recurring',monthly=recurring&&form.elements.frequency.value==='monthly',last=monthly&&form.elements.end_of_month.checked;document.querySelector('#income-frequency-field').hidden=!recurring;document.querySelector('#income-status-field').hidden=recurring;form.elements.status.disabled=recurring;document.querySelector('#month-end-field').hidden=!monthly;document.querySelector('#income-date-field').hidden=last;form.elements.expected_on.disabled=last;form.elements.expected_on.required=!last;document.querySelector('#income-start-month-field').hidden=!last;form.elements.start_month.disabled=!last;form.elements.start_month.required=last;document.querySelector('#income-date-label').textContent=recurring?t("İlk gelirin geleceği tarih"):t("Gelirin geldiği / geleceği tarih");document.querySelector('#income-hint').textContent=last?t("Seçilen aydan başlayarak her ayın son günü planlanır."):recurring?(monthly?t("Seçtiğin gün her ay tekrar eder; kısa aylarda ayın son günü kullanılır."):t("İlk gelir gününden itibaren her 7 günde bir tekrar eder.")):t("Beklenen gelir, alınmış gelir olarak sayılmaz.");const editing=Boolean(form.elements.id.value),record=editing&&form.elements.record_kind.value==='income_record',rule=editing&&form.elements.record_kind.value==='income_rule',source=rule?data.income_rules.find(row=>String(row.id)===form.elements.id.value):record?data.income_records.find(row=>String(row.id)===form.elements.id.value):null;form.elements.income_kind.disabled=editing;form.elements.frequency.disabled=false;form.elements.end_of_month.disabled=false;form.elements.expected_on.readOnly=false;form.elements.start_month.readOnly=false;const showReceived=record&&form.elements.status.value==='received';document.querySelector('#income-received-field').hidden=!showReceived;form.elements.received_on.disabled=!showReceived;form.elements.received_on.required=showReceived;if(showReceived&&!form.elements.received_on.value)form.elements.received_on.value=day();if(rule&&source?.has_receipts)document.querySelector('#income-hint').textContent=t("Tutar değişikliği bugünden sonraki beklenen gelirlere uygulanır; alınmış gelirler korunur. Gün ve sıklık değişikliğinde başlangıcı bugün veya sonrası seç. Gerçekleşen tahsilatlar ayrı kayıtlarda korunur.");if(record&&source?.rule_id)document.querySelector('#income-hint').textContent=t("Bu tahsilatın tutarını ve gerçek alınma tarihini düzeltebilirsin. Plan tarihini değiştirirsen bu kayıt tek seferlik ayrılır; eski tarihte ikinci gelir oluşmaz.");}
function updatePaymentFields(){const form=document.querySelector('#payment-form'),expense=form.elements.entry_kind.value==='expense',regular=form.elements.entry_kind.value==='regular',card=profile?.cards.find(card=>card.id===form.elements.card_ref.value),summary=document.querySelector('#card-due-preview');const cardLinked=Boolean(card)&&!expense;for(const name of ['start_on','end_on']){const field=form.elements[name],value=field.value;field.type=cardLinked?'month':'date';field.value=cardLinked?value.slice(0,7):value.length===7?value+'-01':value;}document.querySelector('#payment-start-field').firstChild.textContent=cardLinked?t("İlk ödeme ayı"):t("İlk ödeme tarihi");document.querySelector('#payment-end-field span').textContent=cardLinked?t("Son ödeme ayı"):t("Son ödeme tarihi");document.querySelector('#payment-frequency-field').hidden=!regular;form.elements.frequency.disabled=!regular;document.querySelector('#payment-card-field').hidden=false;form.elements.card_ref.disabled=false;form.elements.card_ref.options[0].textContent=regular?t("Nakit / banka kartı"):form.elements.id.value?t("Kart seçilmedi"):t("Kredi kartı seç");document.querySelector('#payment-end-label').textContent=cardLinked?t("Son ödeme ayı"):regular?t("Son ödeme tarihi"):t("Taksit bitiş tarihi");document.querySelector('#payment-start-field').hidden=expense;document.querySelector('#payment-end-field').hidden=expense;form.elements.start_on.disabled=expense;form.elements.start_on.required=!expense;form.elements.end_on.disabled=expense;form.elements.end_on.required=!expense;document.querySelector('#purchase-date-field').hidden=!expense;form.elements.purchased_on.disabled=!expense;form.elements.purchased_on.required=expense;form.elements.card_ref.required=expense||(!regular&&!form.elements.id.value);document.querySelector('#payment-amount-label').textContent=expense?t("Harcama tutarı (₺)"):regular?t("Ödeme tutarı (₺)"):t("Aylık taksit tutarı (₺)");summary.hidden=!card;summary.innerHTML=card?.payment_due_day?`<small>${t("KARTIN SON ÖDEME GÜNÜ")}</small><strong>${t("Her ayın")} ${card.payment_due_day}${t(". günü")}</strong><span>${esc(cardLabel(card.id))}</span>`:`<span>${t("Ödeme gününü görmek için son ödeme tarihi tanımlı bir kart seç.")}</span>`;document.querySelector('#payment-hint').textContent=expense?t("Tek seferlik kaydedilir. Ödeme günü seçilen kartın ayarından alınır; alışveriş bugün nakit çıkışı sayılmaz."):regular?t("Banka kartı / nakit seçebilir veya kredi kartını belirtebilirsin. Girdiğin tarih bankadan ödeme yapacağın gündür. Haftalık 7 günde bir, aylık aynı gün tekrarlanır; bitişten sonra ödeme oluşmaz."):t("Tutar her taksit içindir. Bitiş tarihindeki son ödeme de plana dahil edilir.");form.elements.end_on.min=form.elements.start_on.value;const invalid=!expense&&form.elements.end_on.value&&form.elements.start_on.value&&form.elements.end_on.value<form.elements.start_on.value,dateError=document.querySelector('#payment-date-error'),message=invalid?`${t("Son ödeme tarihi (")}${form.elements.end_on.value.length===7?monthLabel(form.elements.end_on.value):dateLabel(form.elements.end_on.value)}${t("), ilk ödeme tarihinden (")}${form.elements.start_on.value.length===7?monthLabel(form.elements.start_on.value):dateLabel(form.elements.start_on.value)}${t(") önce olamaz. Bitiş yılını kontrol et.")}`:'';form.elements.end_on.setCustomValidity(message);dateError.textContent=message;dateError.hidden=!invalid;if(data.rules.find(row=>String(row.id)===form.elements.id.value)?.has_paid)document.querySelector('#payment-hint').textContent+=t(" Ödeme geçmişi bulunan planın tutarı, günü ve kartı korunur; açıklamasını düzenleyebilir veya hatalı kaydı Sil ile geri alınabilir biçimde kaldırabilirsin.");}

// A separate, read-only view. Its month and network responses never change the ledger filters.
async function loadAdvice(){
 if(section!=='recommendations')return;
 const revision=++adviceRevision,month=adviceMonth;
 adviceBusy=true;adviceError='';render();
 try{const result=await api('/api/recommendations?'+new URLSearchParams({month}));if(revision!==adviceRevision||month!==adviceMonth||section!=='recommendations')return;adviceData=result}
 catch(error){if(revision!==adviceRevision||section!=='recommendations'||document.querySelector('#auth-form'))return;adviceError=error.message;adviceData=null}
 finally{if(revision===adviceRevision){adviceBusy=false;if(section==='recommendations'&&!document.querySelector('#auth-form'))render()}}
}
function bindAdvice(){const input=document.querySelector('#advice-month');if(!input)return;const choose=value=>{if(!/^\d{4}-\d{2}$/.test(value))return;adviceMonth=value;adviceData=null;loadAdvice()};input.onchange=()=>choose(input.value);for(const offset of [-1,1])document.querySelector(offset<0?'#advice-previous':'#advice-next').onclick=()=>{const [y,m]=adviceMonth.split('-').map(Number);choose(new Date(Date.UTC(y,m-1+offset,1)).toISOString().slice(0,7))};document.querySelector('#advice-refresh').onclick=loadAdvice}
function adviceText(key,values={}){return esc(t(key).replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??'—')))}
function adviceContent(item){const f=item.facts,v={};for(const [key,value] of Object.entries(f)){v[key]=key.endsWith('_minor')?money(value):key==='date'?dateLabel(value):key==='month'?monthLabel(value):value}
 const content={
 negative_balance:['Kayıtlı bakiyen eksi','Banka / nakit bakiyende {amount_minor} açık görünüyor. Önce başlangıç bakiyesini ve gerçekleşen hareketleri kontrol et.'],
 cash_gap:['Ödeme gününden önce nakit açığı var','Beklenen gelirler zamanında gelse bile {date} günü {amount_minor} açık oluşuyor. Ödeme öncesi kaynak planını gözden geçir; 30 gün içindeki en büyük açık {minimum_minor}.'],
 income_dependency:['Ödeme planın gelecek gelire bağlı','Yeni gelir gelmezse {date} günü {amount_minor} açık oluşuyor. Kayıtlı {income_minor} beklenen gelirin zamanında yatmasını takip et.'],
 overdue_payments:['Vadesi geçmiş ödemelerini kontrol et','Ödenmiş olarak kaydedilmemiş {count} ödeme, toplam {amount_minor}. Gerçekte ödediysen ilgili kaydı güncelle; henüz ödemediysen nakit planına dahil et.'],
 fixed_gap:['Sabit yükümlülükler geliri aşıyor','{month}: kayıtlı gelir {income_minor}, sabit gider {fixed_minor}. Ek harcamalardan önce {amount_minor} açık var. Yalnızca ek harcamayı kısmak bu farkı kapatmaz; gelir veya sabit ödeme planını gözden geçir.'],
 extra_gap:['Sonraki harcama planın için bir sınır belirle','{month}: gelir {income_minor} − sabit gider {fixed_minor} = ek harcama payı {capacity_minor}. Ekstrelerdeki ek harcama {extra_minor}; bu paydan {amount_minor} fazla. Kapanmış harcamalar geri alınamaz; benzer gelecek ayı planlarken bu farkı hedef al.'],
 spending_capacity:['Aylık harcama payını takip et','{month}: sabit giderlerden sonra pay {capacity_minor}, ekstrelerdeki ek harcama {extra_minor}, fark {remaining_minor}. Bu bütçe karşılaştırmasıdır; bankada kullanılabilir para değildir.'],
 extra_focus:['İlk inceleyeceğin kart','{month}: {card_name} üzerinde {amount_minor} ek harcama var; bilinen ek harcamaların %{share_percent} kadarı. Kalemleri kontrol ederek gerçekten azaltabileceğin harcamaları ayır; bu farkın tamamı isteğe bağlı harcama olmayabilir.'],
 future_fixed_gap:['Gelecek aylarda sabit ödeme baskısı var','{month}: kayıtlı gelir {income_minor}, sabit gider {fixed_minor}; ek harcamadan önce {amount_minor} açık. Bu aya ait gelir ve ödeme planını şimdiden gözden geçir.'],
 installment_end:['Yaklaşan taksit bitişi','{description} için son ödeme {date}. Yeni bir yükümlülük eklenmezse {month} ödeme planından itibaren aylık {amount_minor} taksit kalkar. Bu tutar bugünkü bakiyene eklenmez.'],
 spending_comparison:['Geçmiş iki aya göre ek harcama yükselmiş','{month} ek harcaması {extra_minor}. Önceki iki tamamlanmış ekstre ayının ortalaması {average_minor}; fark {amount_minor}. Bu karşılaştırmayı bir sonraki ayın planı için kullan.'],
 data_quality:['Eksik bilgileri tamamla, sonuçları güçlendir','Analizi sınırlayan {count} bilgi veya varsayım var. Aşağıdaki veri kontrolünü incele; eksik veriler sıfır harcama ya da kesin gelir sayılmaz.']
 };const pair=content[item.code];return pair?{title:t(pair[0]),body:adviceText(pair[1],v)}:null}
function adviceIssue(issue){const labels={opening_missing:'Başlangıç banka / nakit bakiyesi tanımlı değil; nakit açığı hesaplanmadı.',income_missing:'Seçili ayda pozitif bir gelir kaydı yok; harcama payı bilinmiyor.',closing_missing:'Bazı kartların ekstre kesim günü eksik; harcama ayı kesin değil.',statement_missing:'Seçili harcama ayında bazı ekstre toplamları eksik.',statement_inconsistent:'Ekstre toplamı, bağlı taksitlerle tutarsız. Kesin nakit önerisi durduruldu.',unassigned_installments:'Kartı seçilmemiş taksitler var. Çift sayım riskine karşı kesin nakit önerisi durduruldu.',overdue_income:'Gecikmiş beklenen gelirler gelecek nakit kaynağı sayılmadı.',automatic_income:'Tarihinde otomatik eklenen gelirler bakiyeye dahil; bankaya gerçekten yatıp yatmadığını kontrol et.',future_statements_missing:'Önümüzdeki 30 günde bazı kartların ekstre toplamı bilinmiyor; ödeme tahmini eksik olabilir.',payment_links_inconsistent:'Ödeme bağlantılarında tutarsızlık var; kesin nakit önerisi durduruldu.',history_limited:'10 yıldan eski yükümlülükler incelenemedi; nakit tahmini kısmi.'};return `<li>${esc(t(labels[issue.code]||'Eksik bilgi'))}${issue.amount_minor!==null?` <b>${money(issue.amount_minor)}</b>`:''}<a class="link" href="#${esc(issue.section)}" data-section="${esc(issue.section)}">${t('Kontrol et')} →</a></li>`}
function recommendationsMarkup(){
 const view=adviceData?.month===adviceMonth?adviceData:null;
 const heading=`<section class="panel advice-intro"><div><p class="eyebrow">${t('VERİLERİNDEN YOL HARİTAN')}</p><h2>${t('Önce neye odaklanmalısın?')}</h2><p class="muted">${t('Kayıtlı gelirlerin, banka bakiyen, kart ekstrelerin ve ödeme planların birlikte değerlendirilir. Bu bölüm kayıtlarını değiştirmez.')}</p></div><div class="month-navigation"><button id="advice-previous" class="secondary compact" aria-label="${t('Önceki ay')}">‹</button><label>${t('Harcama ayı')}<input id="advice-month" type="month" value="${adviceMonth}"></label><button id="advice-next" class="secondary compact" aria-label="${t('Sonraki ay')}">›</button><button id="advice-refresh" class="secondary compact" ${adviceBusy?'disabled':''}>${t('Yenile')}</button></div></section>`;
 if(adviceBusy)return heading+`<section class="panel advice-loading" role="status" aria-busy="true"><h2>${t('Verilerin değerlendiriliyor…')}</h2><p class="muted">${t('Nakit tarihleri ve ekstre ayları ayrı hesaplanıyor.')}</p></section>`;
 if(adviceError)return heading+`<section class="panel" role="alert"><h2>${t('Tavsiyeler yüklenemedi')}</h2><p>${esc(adviceError)}</p><p class="muted">${t('Yenile düğmesiyle tekrar deneyebilirsin. Mevcut kayıtların etkilenmez.')}</p></section>`;
 if(!view)return heading;
 const c=view.cash,blocked=c.blocked,unknown=t('Eksik bilgi'),metric=(value)=>value===null||value===undefined?unknown:money(value),priority={urgent:t('Öncelikli'),warning:t('Dikkat'),info:t('İncele')},basis={cash:t('Ödeme tarihi · Nakit'),spending:t('Kesim ayı · Harcama'),plan:t('Gelecek planı'),data:t('Veri kontrolü')};
 return heading+`<div class="advice-context"><span>${t('Nakit hesabı')}: ${dateLabel(view.as_of)} – ${dateLabel(view.horizon_end)}</span><span>${t('Harcama hesabı')}: ${esc(monthLabel(view.month))}</span><span>${view.coverage.payment_complete&&view.spending.complete&&!view.issues.length?t('Kayıtlı kapsam tamam'):t('Kısmi veriyle analiz')}</span></div><section class="advice-metrics" aria-label="${t('30 günlük nakit senaryosu')}"><article><span>${t('Bugünkü kayıtlı bakiye')}</span><strong>${metric(c.balance_minor)}</strong><small>${t('Gerçekleşen hareketler ve açık olan otomatik gelir ayarı dahil.')}</small></article><article><span>${t('Beklenen gelir gelirse en düşük bakiye')}</span><strong>${blocked?unknown:metric(c.minimum_minor)}</strong><small>${t('Gün sonu neti; aynı gün gelir ve ödeme birlikte sayılır.')}</small></article><article><span>${t('Yeni gelir gelmezse en düşük bakiye')}</span><strong>${blocked?unknown:metric(c.without_income_minimum_minor)}</strong><small>${t('Kayıtlı bekleyen ödemelere göre 30 günlük senaryo.')}</small></article></section><p class="advice-assumption muted">${t('Beklenen gelir garanti değildir. Vadesi geçmiş ödemeler bugün ödenecek varsayılır. Gün içi işlem sırası ve henüz girilmemiş harcamalar bilinmez. Bu sonuçlar harcama izni veya borçlanma önerisi değildir.')}</p><section class="advice-list" aria-label="${t('Öncelik sırasına göre tavsiyeler')}">${view.items.map(item=>{const content=adviceContent(item);return content?`<article class="panel advice-card advice-${esc(item.severity)}"><div class="advice-labels"><span>${priority[item.severity]}</span><small>${basis[item.basis]}</small></div><h2>${esc(content.title)}</h2><p>${content.body}</p><a class="link" href="#${esc(item.section)}" data-section="${esc(item.section)}">${t('İlgili kayıtları incele')} →</a></article>`:''}).join('')||`<article class="panel"><h2>${t('Ek bir uyarı üretilmedi')}</h2><p>${t('Bu sonuç yalnızca kayıtlı verileri kapsar. Kaydedilmemiş giderler veya gelirin gecikmesi sonucu değiştirebilir.')}</p></article>`}</section>${view.issues.length?`<section class="panel advice-quality"><h2>${t('Veri kontrolü ve varsayımlar')}</h2><ul>${view.issues.map(adviceIssue).join('')}</ul></section>`:''}<section class="panel advice-future"><div class="panel-head"><div><h2>${t('Önündeki 3 harcama ayı')}</h2><p class="muted">${t('Yalnızca kayıtlı gelir ve sabit ödeme planları. Eksik gelecek maaş otomatik varsayılmaz; ek harcamalar bu tabloya dahil değildir.')}</p></div></div><div class="advice-future-grid">${view.future_months.map(row=>`<article><h3>${esc(monthLabel(row.month))}</h3><dl><div><dt>${t('Kayıtlı gelir')}</dt><dd>${metric(row.income_minor)}</dd></div><div><dt>${row.fixed_complete?t('Sabit ödeme planı'):t('Bilinen sabit ödemeler')}</dt><dd>${money(row.fixed_minor)}</dd></div><div><dt>${row.gap_minor!==null&&BigInt(row.gap_minor)>0n?t('Ek harcamadan önce açık'):t('Ek harcama için plan payı')}</dt><dd>${metric(row.gap_minor!==null&&BigInt(row.gap_minor)>0n?row.gap_minor:row.capacity_minor)}</dd></div></dl><small>${row.complete?t('Kayıtlı ekstre kapsamı tamam.'):t('Ekstre kapsamı eksik; yeni harcamalar plan payını azaltabilir.')}</small></article>`).join('')}</div></section><section class="panel advice-upcoming"><h2>${t('Önce kontrol edilecek ödemeler')}</h2><p class="muted">${t('Vadesi geçmişler ve önümüzdeki 30 gün; tarihe göre ilk 8 kayıt.')}</p>${view.upcoming_payments.map(row=>`<article><div><b>${esc(financialDescription(row))}</b><small>${dateLabel(row.date)}${row.date<view.as_of?' · '+t('Gecikmiş'):''}</small></div><strong>${money(row.amount_minor)}</strong></article>`).join('')||`<p>${t('Bu kapsamda kayıtlı bekleyen ödeme yok.')}</p>`}</section><p class="muted advice-footer">${t('Harcama sınıflaması ekstre kesim ayına, nakit hesabı son ödeme gününe dayanır. Kartlar, taksitler, gelir kuralları ve gerçekleşen hareketler mevcut hesaplama kaynaklarından okunur.')}</p>`
}

function render(){const title={overview:t("Genel Bakış"),payments:t("Ödemelerim"),income:t("Gelirlerim"),profile:t("Profil ve Ayarlar"),recommendations:t("Tavsiyeler")}[section];root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">₺</span><div><b>${t("Harcama Takibi")}</b><small>${t("KİŞİSEL BÜTÇE")}</small></div></div><nav aria-label="${t("Ana gezinme")}">${[['overview','◷',t("Genel Bakış")],['payments','↗',t("Ödemelerim")],['income','＋',t("Gelirlerim")],['profile','⚙',t("Profil ve Ayarlar")],['recommendations','<svg class="nav-insight" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m3 17 6-6 4 4 8-10M14 5h7v7"/></svg>',t("Tavsiyeler")]].map(([id,icon,label])=>`<a href="#${id}" data-section="${id}" ${section===id?'aria-current="page"':''}>${icon}　${label}</a>`).join('')}</nav><div class="side-bottom"><button class="profile-switch" id="open-profile"><b>${esc(profile?.display_name||t("Profil"))}</b><small>${esc(profile?.email||t("Hesap bilgileri"))}</small></button><button class="link" id="logout">${t("Çıkış yap ↗")}</button></div></aside><main class="content"><header class="${section==='recommendations'?'advice-header':''}"><div><p class="eyebrow">${t("GELİR · ÖDEME · KALAN")}</p><h1>${title}</h1><p class="muted">${section==='recommendations'?esc(monthLabel(adviceMonth)):section==='overview'?esc(monthLabel(selectedMonth)):dateLabel(start)+' – '+dateLabel(end)}</p></div>${themeToggleMarkup()}</header>${section==='overview'?`<details class="overall-range"><summary>${t("Genel toplamların tarih aralığını değiştir")}</summary>`:''}<section class="simple-period" ${section==='recommendations'?'hidden':''}><label>${t("Başlangıç")}<input id="period-start" type="date" value="${start}"></label><label>${t("Bitiş")}<input id="period-end" type="date" value="${end}"></label><button class="secondary compact" id="show-period">${t("Göster")}</button><button class="link" id="three-months">${t("Önümüzdeki ay")}</button><button class="link" id="all-payments">${t("Tüm taksitler")}</button></section>${section==='overview'?'</details>':''}<p class="error-banner" id="action-error" role="alert"></p><p class="success-note" id="success" role="status"></p>${data.local_sandbox?`<p class="success-note"><b>${t("Yerel çalışma kopyası.")}</b> ${t("Değişiklikleri burada deneyebilirsin; canlı hesabına aktarılmaz.")}</p>`:''}${data.read_only_preview?`<p class="success-note"><b>${t("Yerel, salt okunur önizleme.")}</b> ${t("Gerçek hesabından okunan veriler gösteriliyor. Buradaki işlemler canlı kayıtlara kaydedilmez.")}</p>`:''}${section==='overview'?overviewMarkup():section==='payments'?paymentsMarkup():section==='profile'?profileMarkup():section==='recommendations'?recommendationsMarkup():incomeMarkup()}</main></div>${dialogs()}`;bind()}
function openIncome(row,kind='income_record'){const form=document.querySelector('#income-form');form.reset();form.elements.id.value=row?.id||'';form.elements.record_kind.value=row?kind:'';form.elements.revision.value=row?.revision||'';form.elements.request_key.value=crypto.randomUUID();const rule=row&&kind==='income_rule';form.elements.income_kind.value=rule?'recurring':'once';form.elements.description.value=row?.description||'';form.elements.amount.value=row?inputMoney(row.amount_minor):'';form.elements.frequency.value=rule&&row.frequency==='weekly'?'weekly':'monthly';form.elements.expected_on.value=row?(rule?row.start_on:row.expected_on):day();form.elements.start_month.value=(rule?row.start_on:day()).slice(0,7);form.elements.end_of_month.checked=Boolean(rule&&row.schedule_mode==='last_day');form.elements.status.value=!rule&&row?.status==='received'?'received':'expected';form.elements.received_on.value=row?.received_on||day();document.querySelector('#income-title').textContent=row?(rule?t("Düzenli geliri düzenle"):t("Geliri düzenle")):t("Gelir ekle");document.querySelector('#income-error').textContent='';updateIncomeFields();document.querySelector('#income-dialog').showModal()}
function openPayment(rule){const form=document.querySelector('#payment-form');form.reset();form.elements.start_on.type='date';form.elements.end_on.type='date';form.elements.id.value=rule?.id||'';form.elements.request_key.value=crypto.randomUUID();form.elements.entry_kind.value=rule?.entry_kind||'installment';form.elements.frequency.value=rule?.frequency==='weekly'?'weekly':'monthly';form.elements.description.value=rule?.description||'';form.elements.amount.value=rule?inputMoney(rule.amount_minor):'';form.elements.start_on.value=rule?.start_on||day();form.elements.end_on.value=rule?.end_on||'';form.elements.purchased_on.value=rule?.purchased_on||day();form.elements.card_ref.innerHTML=`<option value="">${t("Banka / nakit (kart kullanmadan)")}</option>`+(profile?.cards||[]).filter(card=>card.active||card.id===rule?.card_ref).map(card=>`<option value="${esc(card.id)}">${esc(cardLabel(card.id))}${card.active?'':' · Pasif'}</option>`).join('');form.elements.card_ref.value=rule?.card_ref||'';document.querySelector('#payment-title').textContent=rule?t("Kaydı düzenle"):t("Taksit / harcama ekle");document.querySelector('#payment-error').textContent='';updatePaymentFields();document.querySelector('#payment-dialog').showModal()}
async function submit(form,errorId,operation){const button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;document.querySelector(errorId).textContent='';try{await operation();form.closest('dialog').close();await load();const message=document.querySelector('#success');if(message)message.textContent=t("Kaydedildi.")}catch(error){document.querySelector(errorId).textContent=error.message}finally{button.disabled=false}}
function bind(){bindAdvice();const openingButton=document.querySelector('#new-opening');if(openingButton)openingButton.onclick=()=>{const form=document.querySelector('#opening-form');form.reset();const position=monthlyData?.cash_position||data.cash_position;form.elements.amount.value=position?.configured?inputMoney(position.opening_balance_minor):'';form.elements.effective_on.value=position?.effective_on||day();form.elements.revision.value=position?.revision||'';form.elements.auto_income_on_due.checked=Boolean(position?.auto_income_on_due);document.querySelector('#opening-error').textContent='';document.querySelector('#opening-dialog').showModal()};document.querySelector('#opening-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#opening-error',()=>api('/api/simple-opening',{method:'PUT',body:JSON.stringify({...Object.fromEntries(new FormData(form)),auto_income_on_due:form.elements.auto_income_on_due.checked})}))};const monthInput=document.querySelector('#overview-month');if(monthInput){monthInput.onchange=()=>{if(/^\d{4}-\d{2}$/.test(monthInput.value)){selectedMonth=monthInput.value;load()}};document.querySelector('#previous-month').onclick=()=>shiftOverviewMonth(-1);document.querySelector('#next-month').onclick=()=>shiftOverviewMonth(1);document.querySelector('#current-month').onclick=()=>{selectedMonth=day().slice(0,7);load()}};document.querySelector('#open-profile').onclick=()=>{section='profile';history.replaceState(null,'','#profile');render()};if(data.read_only_preview){document.querySelectorAll('form:not(#auth-form) button[type=submit],[data-rule-status]').forEach(button=>{button.disabled=true;button.title=t("Salt okunur önizlemede kayıt değiştirme kapalı")})}document.querySelectorAll('[data-section]').forEach(link=>link.onclick=event=>{event.preventDefault();section=link.dataset.section;history.replaceState(null,'','#'+section);render();if(section==='recommendations')loadAdvice()});document.querySelector('#logout').onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'});csrf='';authView()};document.querySelector('#show-period').onclick=()=>{start=document.querySelector('#period-start').value;end=document.querySelector('#period-end').value;load()};document.querySelector('#three-months').onclick=()=>{({start,end}=nextCalendarMonth());load()};document.querySelector('#all-payments').onclick=()=>{start=day().slice(0,7)+'-01';end=data.rules.filter(rule=>rule.status==='active'&&rule.end_on).map(rule=>rule.end_on).sort().at(-1)||plusMonths(day(),12);load()};document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.close).close());document.querySelectorAll('[data-card-total]').forEach(form=>{form.elements.due_day_offset.onchange=()=>{const card=(cardDebtData||monthlyData).card_monthly_debt.cards.find(row=>row.card_ref===form.dataset.cardTotal);form.querySelector('output').textContent=dateLabel(cardDuePreview(card,(cardDebtData||monthlyData).card_monthly_debt.month,Number(form.elements.due_day_offset.value)));};form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button'),error=form.querySelector('.error'),card=(cardDebtData||monthlyData).card_monthly_debt.cards.find(row=>row.card_ref===form.dataset.cardTotal);if(button.disabled)return;button.disabled=true;button.textContent=t("Kaydediliyor…");error.textContent='';try{await api('/api/simple-card-monthly-total',{method:'PUT',body:JSON.stringify({card_ref:card.card_ref,month:(cardDebtData||monthlyData).card_monthly_debt.month,source_month:card.source_month,due_day_offset:Number(form.elements.due_day_offset.value),amount:form.elements.amount.value,version:card.version})});chooseDebtMonth((cardDebtData||monthlyData).card_monthly_debt.month);await load();document.querySelector('#success').textContent=t("Aylık kart borcu kaydedildi.")}catch(problem){error.textContent=problem.message;button.disabled=false;button.textContent=t("Borcu kaydet")}}});const spendingMonth=document.querySelector('#spending-month');if(spendingMonth)spendingMonth.onchange=()=>{if(/^\d{4}-\d{2}$/.test(spendingMonth.value)){chooseDebtMonth(spendingMonth.value);load()}};const newExtra=document.querySelector('#new-extra');if(newExtra)newExtra.onclick=()=>{openPayment();const form=document.querySelector('#payment-form');form.elements.entry_kind.value='expense';updatePaymentFields()};const newPayment=document.querySelector('#new-payment');if(newPayment)newPayment.onclick=()=>openPayment();document.querySelectorAll('[data-edit-rule]').forEach(button=>button.onclick=()=>openPayment(data.rules.find(rule=>String(rule.id)===button.dataset.editRule)));document.querySelectorAll('[data-rule-status]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/recurring/${button.dataset.ruleStatus}/status`,{method:'POST',body:JSON.stringify({status:button.dataset.status})});await load()}catch(error){document.querySelector('#action-error').textContent=error.message;button.disabled=false}});
 const profileForm=document.querySelector('#profile-form');if(profileForm){const input=profileForm.elements.display_name,username=profileForm.elements.username,button=profileForm.querySelector('button[type=submit]'),saved=profile.display_name;const update=()=>{const dirty=(input.value.trim()!==saved||username.value.trim().toLowerCase()!==(profile.username||''))&&input.value.trim().length>0&&username.value.trim().length>=3&&!data.read_only_preview;button.disabled=!dirty;button.classList.toggle('primary',dirty);button.classList.toggle('secondary',!dirty);};input.addEventListener('input',update);username.addEventListener('input',update);update();profileForm.onsubmit=async event=>{event.preventDefault();if(button.disabled)return;button.disabled=true;button.textContent=t("Kaydediliyor…");profileForm.setAttribute('aria-busy','true');try{await api('/api/profile',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(profileForm)))});await load();document.querySelector('#success').textContent=t("Profil kaydedildi.")}catch(error){const target=document.querySelector('#profile-error');if(target)target.textContent=error.message;button.textContent=t("Profili kaydet");update();}finally{profileForm.setAttribute('aria-busy','false')}};}
 const newCard=document.querySelector('#new-card');if(newCard)newCard.onclick=()=>openCard();document.querySelectorAll('[data-edit-profile-card]').forEach(button=>button.onclick=()=>openCard(profile.cards.find(card=>card.id===button.dataset.editProfileCard)));document.querySelector('#card-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#card-error',async()=>{const payload=Object.fromEntries(new FormData(form));payload.version=Number(payload.version);payload.active=Number(payload.active);await api('/api/profile/cards',{method:'POST',body:JSON.stringify(payload)})})};
 const paymentForm=document.querySelector('#payment-form');paymentForm.elements.entry_kind.onchange=updatePaymentFields;paymentForm.elements.start_on.oninput=updatePaymentFields;paymentForm.elements.end_on.oninput=updatePaymentFields;paymentForm.elements.card_ref.onchange=()=>{const card=profile?.cards.find(card=>card.id===paymentForm.elements.card_ref.value);if(card?.payment_due_on&&!paymentForm.elements.id.value&&paymentForm.elements.entry_kind.value==='installment')paymentForm.elements.start_on.value=card.payment_due_on;updatePaymentFields()};paymentForm.onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#payment-error',async()=>{const payload=Object.fromEntries(new FormData(form)),old=data.rules.find(rule=>String(rule.id)===payload.id);if(payload.card_ref){const card=profile.cards.find(card=>card.id===payload.card_ref);for(const field of ['start_on','end_on'])if(payload[field]?.length===7)payload[field]=cardDuePreview(card,payload[field]);}payload.frequency=payload.entry_kind==='regular'?form.elements.frequency.value:old?.frequency||'monthly';if(old){payload.category_id=old.category_id;payload.payment_method_id=old.payment_method_id;payload.revision=old.revision}if(payload.entry_kind==='expense'){const card=profile.cards.find(card=>card.id===payload.card_ref);if(!card?.payment_due_on)throw Error(t("Kartın son ödeme tarihini Profil ve Ayarlar bölümünden gir."));delete payload.start_on;}await api('/api/simple-payment-plans',{method:'POST',body:JSON.stringify(payload)})})};
 const newIncome=document.querySelector('#new-income');if(newIncome)newIncome.onclick=()=>openIncome();document.querySelectorAll('[data-edit-income]').forEach(button=>button.onclick=()=>{const kind=button.dataset.incomeKind,row=(kind==='income_rule'?data.income_rules:data.income_records).find(row=>String(row.id)===button.dataset.editIncome);openIncome(row,kind)});const incomeForm=document.querySelector('#income-form');for(const name of ['income_kind','frequency','end_of_month','status'])incomeForm.elements[name].onchange=updateIncomeFields;incomeForm.onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#income-error',async()=>{const payload=Object.fromEntries(new FormData(form)),recurring=form.elements.income_kind.value==='recurring',editing=Boolean(form.elements.id.value);payload.frequency=recurring?form.elements.frequency.value:'once';payload.schedule_mode=recurring&&payload.frequency==='monthly'&&form.elements.end_of_month.checked?'last_day':'anchored';if(payload.schedule_mode==='last_day'){payload.start_month=form.elements.start_month.value;if(editing)payload.expected_on=payload.start_month+'-01';else{delete payload.expected_on;delete payload.start_on;}}await api('/api/simple-income',{method:editing?'PUT':'POST',body:JSON.stringify(payload)})})};
 document.querySelectorAll('[data-delete-kind]').forEach(button=>button.onclick=()=>{const kind=button.dataset.deleteKind,list=kind==='payment_plan'?data.rules:kind==='income_rule'?data.income_rules:data.income_records,row=list.find(row=>String(row.id)===button.dataset.recordId),form=document.querySelector('#delete-form');form.reset();form.elements.record_kind.value=kind;form.elements.id.value=row.id;form.elements.revision.value=kind==='payment_plan'?row.deletion_revision:row.revision;document.querySelector('#delete-name').textContent=row.description;document.querySelector('#delete-impact').textContent=kind==='income_rule'?t("Bu düzenli gelir planı ve ona bağlı tüm tahsilat kayıtları hesaplamalardan çıkarılacak. Mevcut banka bakiyesi ve tahmin yeniden hesaplanacak."):kind==='payment_plan'?t("Bu harcama / ödeme planı ve ona bağlı gerçekleşen ödemeler hesaplamalardan çıkarılacak. Ayrı girdiğin toplam kart borcu ve kart ödemeleri korunacak."):t("Bu gelir hesabından kaldırılacak. Alınmış bir gelir ise banka bakiyesindeki etkisi de geri alınacak.");document.querySelector('#delete-error').textContent='';document.querySelector('#delete-dialog').showModal()});document.querySelector('#delete-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;try{const deleted=await api('/api/simple-records/delete',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),confirmation:'SİL'})});document.querySelector('#delete-dialog').close();await load();const note=document.querySelector('#success');note.innerHTML=`${t("Kayıt silindi.")} <button class="link" id="undo-delete">${t("Geri al")}</button>`;document.querySelector('#undo-delete').onclick=async()=>{const undo=document.querySelector('#undo-delete');undo.disabled=true;try{await api('/api/simple-records/restore',{method:'POST',body:JSON.stringify(deleted)});await load();document.querySelector('#success').textContent=t("Kayıt geri alındı.")}catch(problem){document.querySelector('#action-error').textContent=problem.message;undo.disabled=false}}}catch(problem){document.querySelector('#delete-error').textContent=problem.message;button.disabled=false}};
 document.querySelectorAll('[data-pay]').forEach(button=>button.onclick=()=>{const event=findEvent(button.dataset.pay),form=document.querySelector('#paid-form');form.reset();form.elements.event_id.value=event.id;form.elements.request_key.value=crypto.randomUUID();form.elements.amount.value=inputMoney(event.amount_minor);form.elements.paid_on.value=day();document.querySelector('#paid-description').textContent=event.description+t(" · Planlanan ")+dateLabel(event.date);document.querySelector('#paid-error').textContent='';document.querySelector('#paid-dialog').showModal()});document.querySelector('#paid-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#paid-error',async()=>{const payload=Object.fromEntries(new FormData(form)),row=findEvent(payload.event_id);payload.scheduled_on=row.scheduled_on;if(row.monthly_card_ref){payload.card_ref=row.monthly_card_ref;payload.month=row.monthly_month;await api('/api/simple-card-monthly-payments',{method:'POST',body:JSON.stringify(payload)})}else if(row.statement_id){payload.statement_id=row.statement_id;await api('/api/simple-statement-payments',{method:'POST',body:JSON.stringify(payload)})}else await api(`/api/simple-payments/${row.recurring_id}/complete`,{method:'POST',body:JSON.stringify(payload)})})};
 document.querySelectorAll('[data-receive]').forEach(button=>button.onclick=()=>{const row=findEvent(button.dataset.receive),form=document.querySelector('#received-form');form.reset();form.elements.event_id.value=row.id;form.elements.received_on.value=day();document.querySelector('#received-description').textContent=row.description;document.querySelector('#received-error').textContent='';document.querySelector('#received-dialog').showModal()});document.querySelector('#received-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#received-error',async()=>{const row=findEvent(form.elements.event_id.value);await api('/api/simple-income/receive',{method:'POST',body:JSON.stringify({record_id:row.record_id,rule_id:row.rule_id,scheduled_on:row.scheduled_on,expected_amount_minor:row.amount_minor,received_on:form.elements.received_on.value})})})};}
function navigateHash(){const target=location.hash.slice(1);if(!data||document.querySelector('#auth-form')||target===section||!['overview','payments','income','profile','recommendations'].includes(target))return;section=target;render();if(section==='recommendations')loadAdvice()}
if(typeof window!=='undefined')window.addEventListener('hashchange',navigateHash);
function refreshCashDate(){if(data&&data.as_of!==day()&&document.visibilityState!=='hidden'&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest('form')&&!document.querySelector('.profile-form button[type=submit]:not(:disabled)'))load()}
if(typeof window!=='undefined'){window.setInterval(refreshCashDate,60000);window.addEventListener('focus',refreshCashDate);document.addEventListener('visibilitychange',refreshCashDate)}
(async()=>{try{const session=await api('/api/session');privateBeta=Boolean(session.private_beta);if(!session.user_id){authView();return}csrf=session.csrf;const hash=location.hash.slice(1);if(['overview','payments','income','profile','recommendations'].includes(hash))section=hash;await load()}catch(error){authView()}})();
